<script setup lang="ts">
import type { StoreArticle } from '~~/shared/types/store'
const props = defineProps<{ articles: StoreArticle[] }>()
const selected = ref(0)
watch(() => props.articles.map(a => a.id).join(','), () => { selected.value = 0 })
const current = computed(() => props.articles[selected.value] || props.articles[0])
const money = useMoney()
</script>
